<script setup lang="ts">
import {ref,computed,watch,onMounted,onUnmounted,toRaw,nextTick} from 'vue';
import {normalizeWidget,widgetThemes,type WidgetSettings} from '../lib/widget';
import {api} from '../lib/api';import type {Bootstrap} from '../lib/model';
import Icon from './Icon.vue';import Toggle from './ui/Toggle.vue';import SahdevOrb from './SahdevOrb.vue';
import '../styles/widget-studio.css';
const props=defineProps<{state:Bootstrap}>(),emit=defineEmits<{refresh:[];conversation:[id:string]}>();
const draft=ref<WidgetSettings>(normalizeWidget(structuredClone(toRaw(props.state.workspace.intelligence?.widget))));
const saved=ref(JSON.stringify(draft.value)),dirty=computed(()=>JSON.stringify(draft.value)!==saved.value);
const section=ref('appearance'),mode=ref<'design'|'live'>('design'),device=ref('desktop'),frame=ref<HTMLIFrameElement>(),frameKey=ref(0);
const busy=ref(false),error=ref(''),notice=ref(''),originInput=ref(''),conversationId=ref(''),connection=ref('');
const installations=ref<{origin:string;last_seen_at:string;last_message_at:string|null}[]>([]);
const canEdit=computed(()=>['owner','admin'].includes(props.state.session.role));
const canBrand=computed(()=>props.state.workspace.sample||props.state.entitlement?.plan.features.customBranding);
const origin=typeof location==='undefined'?'':location.origin;
const embed=computed(()=>`<script src="${origin}/widget.js" data-workspace="${props.state.workspace.id}" defer><\/script>`);
const frameUrl=computed(()=>`/widget-preview/?workspace=${encodeURIComponent(props.state.workspace.id)}&mode=${mode.value}&v=${frameKey.value}`);
const chosenTheme=computed(()=>widgetThemes.find(t=>t.id===draft.value.theme)||widgetThemes[0]);
const quickText=computed({get:()=>draft.value.quickReplies.join('\n'),set:(v:string)=>draft.value.quickReplies=v.split('\n').map(s=>s.trim()).filter(Boolean).slice(0,4)});
const steps=[{id:'appearance',icon:'sparkles',name:'Appearance'},{id:'content',icon:'chat',name:'Content'},{id:'behavior',icon:'settings',name:'Behavior'},{id:'install',icon:'globe',name:'Install & test'}];
function preview(){frame.value?.contentWindow?.postMessage({type:'sahdev:preview-config',config:JSON.parse(JSON.stringify(draft.value))},origin);}
watch(draft,()=>{if(mode.value==='design')preview();},{deep:true});
watch(()=>props.state.workspace.intelligence?.widget,value=>{if(!dirty.value){draft.value=normalizeWidget(structuredClone(toRaw(value)));saved.value=JSON.stringify(draft.value);}},{deep:true});
function chooseTheme(theme:typeof widgetThemes[number]){Object.assign(draft.value,{theme:theme.id,accent:theme.accent,radius:theme.radius,appearance:theme.appearance,font:theme.font,avatar:'orb'});}
async function save(){if(!canEdit.value||busy.value)return false;busy.value=true;error.value='';notice.value='';try{
 const current:Bootstrap=await api('/bootstrap',{workspace:props.state.workspace.id});
 if(JSON.stringify(normalizeWidget(current.workspace.intelligence?.widget))!==saved.value){throw new Error('Another administrator changed this widget. Reload saved settings before applying your edits.');}
 await api('/intelligence/widget',{method:'PATCH',body:draft.value,workspace:props.state.workspace.id,version:current.version});saved.value=JSON.stringify(draft.value);notice.value='Widget saved. New page loads use these settings.';emit('refresh');if(mode.value==='live')frameKey.value++;return true;
 }catch(e:any){error.value=e.message;return false;}finally{busy.value=false;}}
function reloadSaved(){draft.value=normalizeWidget(structuredClone(toRaw(props.state.workspace.intelligence?.widget)));saved.value=JSON.stringify(draft.value);error.value='';notice.value='Saved settings restored.';}
function addOrigin(){try{const value=originInput.value.trim(),u=new URL(value);if(u.origin!==value||!(u.protocol==='https:'||u.protocol==='http:'&&['localhost','127.0.0.1'].includes(u.hostname)))throw new Error();if(!draft.value.allowedOrigins.includes(value))draft.value.allowedOrigins.push(value);originInput.value='';error.value='';}catch{error.value='Enter an exact HTTPS origin, for example https://manage.hostingspell.com (no path or trailing slash).';}}
async function liveTest(){if(!canEdit.value){error.value='An administrator must enable the preview origin first.';return;}if(!draft.value.allowedOrigins.includes(origin))draft.value.allowedOrigins.push(origin);if(dirty.value&&!await save())return;mode.value='live';connection.value='Connecting to your saved widget…';frameKey.value++;await refreshInstallations();}
async function copy(){try{await navigator.clipboard.writeText(embed.value);notice.value='Embed code copied.';}catch{error.value='Clipboard access is unavailable. Select and copy the snippet below.';}}
async function refreshInstallations(){try{const r=await api('/intelligence/widget/installations',{workspace:props.state.workspace.id});installations.value=r.installations;}catch(e:any){error.value=e.message;}}
function event(e:MessageEvent){if(e.origin!==origin||e.source!==frame.value?.contentWindow)return;if(e.data?.type==='sahdev:preview-loaded')preview();if(e.data?.type==='sahdev:ready')connection.value=e.data.preview?'':'Connected to the saved widget';if(e.data?.type==='sahdev:error')connection.value=e.data.message;if(e.data?.type==='sahdev:conversation'){conversationId.value=e.data.conversationId;connection.value='Conversation saved · '+e.data.status;}}
function changeMode(value:'design'|'live'){if(value==='live')liveTest();else{mode.value='design';connection.value='';frameKey.value++;nextTick(preview);}}
onMounted(()=>{window.addEventListener('message',event);refreshInstallations();});onUnmounted(()=>window.removeEventListener('message',event));
</script>
<template><div class="widget-studio">
 <header class="studio-heading"><div><span class="studio-eyebrow">YOUR BRAND. A REAL CONVERSATION.</span><h1>Widget studio<span class="studio-dot"></span></h1><p>Make Sahdev feel at home on your website.</p></div><div class="studio-save"><span :class="['save-state',{unsaved:dirty}]">{{dirty?'Unsaved changes':'All changes saved'}}</span><button class="button primary" :disabled="busy||!canEdit" @click="save"><Icon name="check" :size="16"/>{{busy?'Saving…':'Save widget'}}</button></div></header>
 <p v-if="error" class="form-error" role="alert">{{error}} <button class="text-action" @click="reloadSaved">Reload saved settings</button></p><p v-if="notice" class="success-banner" role="status">{{notice}}</p>
 <div class="studio-layout"><section class="studio-editor"><nav class="studio-tabs" aria-label="Widget settings"><button v-for="step in steps" :key="step.id" :class="{active:section===step.id}" @click="section=step.id"><Icon :name="step.icon" :size="16"/>{{step.name}}</button></nav>
 <fieldset :disabled="!canEdit||busy" class="studio-fields">
 <template v-if="section==='appearance'"><div class="studio-section-title"><span class="studio-number">01</span><div><h2>Choose your personality</h2><p>Distinct layouts, textures, and conversation styles.</p></div></div>
 <div class="widget-theme-grid"><button v-for="theme in widgetThemes" :key="theme.id" :class="['widget-theme-card',{selected:draft.theme===theme.id}]" type="button" :aria-pressed="draft.theme===theme.id" @click="chooseTheme(theme)"><div :class="['theme-mini',theme.appearance,theme.id]" :style="{'--mini-accent':theme.accent}"><div><SahdevOrb :size="20" :motion="false"/><i></i><b v-if="draft.theme===theme.id">✓</b></div><span></span><span></span><em></em></div><strong>{{theme.name}}</strong><small>{{theme.description}}</small></button></div>
 <div class="studio-section-title"><span class="studio-number">02</span><div><h2>The Sahdev signature</h2><p>The fluid orb from your original support experience.</p></div></div>
 <div class="orb-control"><SahdevOrb :size="62" :palette="draft.orbPalette" :motion="draft.orbMotion"/><div><label>Orb palette<select v-model="draft.orbPalette"><option value="aurora">Original · coral, violet & blue</option><option value="ocean">Ocean · cyan & cobalt</option><option value="sunset">Sunset · amber & rose</option><option value="mono">Chrome · silver & charcoal</option></select></label><div class="studio-inline"><span>Animate orb</span><Toggle v-model="draft.orbMotion" label="Animate orb"/></div></div></div>
 <div class="studio-form-grid"><label>Avatar<select v-model="draft.avatar"><option value="orb">Animated Sahdev orb</option><option value="logo">My logo</option></select></label><label v-if="draft.avatar==='logo'">Logo URL<input v-model="draft.logoUrl" type="url" placeholder="https://example.com/logo.png" maxlength="2000"/></label><label>Color mode<select v-model="draft.appearance"><option value="light">Light</option><option value="dark">Dark</option><option value="auto">Match visitor’s device</option></select></label><label>Accent color<div class="color-input"><input v-model="draft.accent" type="color" aria-label="Choose accent color"/><input v-model="draft.accent" aria-label="Accent hex value" pattern="#[0-9a-fA-F]{6}" maxlength="7"/></div></label><label>Typography<select v-model="draft.font"><option value="system">Modern sans</option><option value="rounded">Friendly rounded</option><option value="mono">Technical mono</option></select></label><label>Corner radius <span>{{draft.radius}} px</span><input v-model.number="draft.radius" type="range" min="0" max="28"/></label><label>Panel width <span>{{draft.width}} px</span><input v-model.number="draft.width" type="range" min="320" max="480" step="10"/></label></div>
 <div class="studio-tip"><Icon name="shield" :size="16"/><p>The widget respects reduced-motion preferences and adapts to phone screens automatically.</p></div>
 </template>
 <template v-else-if="section==='content'"><div class="studio-section-title"><span class="studio-number">01</span><div><h2>A familiar first hello</h2><p>Set the identity and language visitors see.</p></div></div><div class="studio-form-grid"><label class="full">Assistant display name<input v-model="draft.title" maxlength="80"/></label><label class="full">Subtitle<input v-model="draft.subtitle" maxlength="180"/></label><label class="full">Welcome message<textarea v-model="draft.welcome" rows="3" maxlength="500"/></label><label class="full">Message placeholder<input v-model="draft.placeholder" maxlength="80"/></label><label class="full">Conversation starters<textarea v-model="quickText" rows="4" placeholder="One suggestion per line"/><small>Up to 4 suggestions, 80 characters each. Selecting one fills the visitor’s draft.</small></label></div><div class="studio-section-title"><span class="studio-number">02</span><div><h2>Helpful places to go</h2><p>Every tab opens a working part of your support flow.</p></div></div><div class="studio-toggle"><div><strong>Help articles</strong><p>Search published, public knowledge. Internal drafts stay private.</p></div><Toggle v-model="draft.enableKnowledge" label="Enable help articles"/></div><div class="studio-toggle"><div><strong>Support tickets</strong><p>Create a ticket or carry the current chat transcript into a ticket.</p></div><Toggle v-model="draft.enableTickets" label="Enable support tickets"/></div><div class="studio-toggle"><div><strong>Message timestamps</strong><p>Show each reply’s time in the visitor’s local timezone.</p></div><Toggle v-model="draft.showTimestamps" label="Show message timestamps"/></div><div class="studio-tip"><Icon name="sparkles" :size="16"/><p>Messages go to your human support team. Automatic AI replies remain off until you connect and enable a provider.</p></div></template>
 <template v-else-if="section==='behavior'"><div class="studio-section-title"><span class="studio-number">01</span><div><h2>Launch it your way</h2><p>Placement, availability, and the details you ask for.</p></div></div><div class="studio-toggle"><div><strong>Accept new conversations</strong><p>Pausing keeps existing threads and replies available.</p></div><Toggle v-model="draft.enabled" label="Accept new conversations"/></div><div class="studio-form-grid"><label class="full">Launcher label<input v-model="draft.launcher" maxlength="60"/></label><label>Launcher style<select v-model="draft.launcherStyle"><option value="pill">Orb + label</option><option value="orb">Orb only</option></select></label><label>Position<select v-model="draft.position"><option value="right">Bottom right</option><option value="left">Bottom left</option></select></label><label>Edge spacing <span>{{draft.offset}} px</span><input v-model.number="draft.offset" type="range" min="8" max="64"/></label><label>Availability<select v-model="draft.availability"><option value="available">Accepting messages</option><option value="away">Away · leave a message</option></select></label><label v-if="draft.availability==='away'" class="full">Away message<textarea v-model="draft.awayMessage" rows="3" maxlength="500"/></label></div><div class="studio-section-title"><span class="studio-number">02</span><div><h2>Know who’s reaching out</h2><p>Contact details are unverified and never unlock an existing account.</p></div></div><div class="studio-form-grid"><label>Ask for name<select v-model="draft.nameField"><option value="off">Don’t ask</option><option value="optional">Optional</option><option value="required">Required</option></select></label><label>Ask for email<select v-model="draft.emailField"><option value="off">Don’t ask</option><option value="optional">Optional</option><option value="required">Required</option></select></label><label class="full">Privacy policy URL<input v-model="draft.privacyUrl" type="url" placeholder="https://example.com/privacy"/></label></div><div class="studio-toggle"><div><strong>Sahdev attribution</strong><p>{{canBrand?'You can hide branding on this workspace.':'Brand removal is available with an eligible plan.'}}</p></div><Toggle v-model="draft.showBranding" label="Show Sahdev attribution" :disabled="!canBrand"/></div></template>
 <template v-else><div class="studio-section-title"><span class="studio-number">01</span><div><h2>Allow your website</h2><p>Authorize each exact origin where the widget should load.</p></div></div><form class="origin-add" @submit.prevent="addOrigin"><input v-model="originInput" aria-label="Website origin" placeholder="https://manage.hostingspell.com"/><button class="button secondary small" type="submit"><Icon name="plus" :size="15"/>Add</button></form><div class="origin-list"><div v-for="value in draft.allowedOrigins" :key="value"><Icon name="globe" :size="15"/><code>{{value}}</code><button type="button" :aria-label="'Remove '+value" @click="draft.allowedOrigins=draft.allowedOrigins.filter(o=>o!==value)"><Icon name="x" :size="14"/></button></div><p v-if="!draft.allowedOrigins.length" class="studio-empty">No websites allowed yet. Add your website above.</p></div><small class="studio-help">Use the origin only: https://manage.hostingspell.com, without /dj/ or a trailing slash. Save after adding it.</small>
 <div class="studio-section-title"><span class="studio-number">02</span><div><h2>Add the embed code</h2><p>Paste before the closing &lt;/body&gt; tag on your website.</p></div></div><div class="snippet-head"><span>HTML · one script, no dependencies</span><button type="button" @click="copy"><Icon name="copy" :size="14"/>Copy code</button></div><pre class="studio-snippet" tabindex="0">{{embed}}</pre><details class="install-notes"><summary>WordPress, WHMCS & custom websites</summary><p><b>WordPress:</b> Add the snippet with your theme’s footer scripts option or a trusted code-snippets plugin.</p><p><b>WHMCS:</b> Add to your client-area footer template using your normal deployment process.</p><p><b>Custom site:</b> Paste it into the shared layout. Allow this Site’s script, style and API origin in your Content Security Policy if you use one.</p></details>
 <div class="studio-section-title"><span class="studio-number">03</span><div><h2>Verify a real conversation</h2><p>Send a visitor message, then reply from Shared inbox.</p></div></div><button class="button primary" type="button" @click="liveTest"><Icon name="chat" :size="16"/>Save & test live chat</button><p class="studio-help">This adds {{origin}} to your allowed origins. Test messages create real inbox records.</p><div class="studio-tip warning"><Icon name="globe" :size="17"/><p><strong>Public access is required for an external embed.</strong> An owner-private ChatGPT Site returns a sign-in page to visitors instead of the widget script. Public widget access does not grant access to your workspace records.</p></div>
 <div class="install-status-title"><h3>Installation activity</h3><button type="button" class="text-action" @click="refreshInstallations"><Icon name="refresh" :size="13"/>Refresh</button></div><div v-for="value in draft.allowedOrigins" :key="value" class="install-status"><span>{{value}}</span><small v-if="installations.find(i=>i.origin===value)">Last loaded {{new Date(installations.find(i=>i.origin===value)!.last_seen_at).toLocaleString()}}</small><small v-else>Not seen yet · open your installed page after saving</small></div>
 </template></fieldset></section>
 <aside class="studio-preview"><div class="preview-toolbar"><div><span class="studio-eyebrow">{{mode==='design'?'YOUR WIDGET, IN CONTEXT':'CONNECTED TO YOUR INBOX'}}</span><strong>{{chosenTheme.name}}</strong></div><div class="device-switch" aria-label="Preview width"><button :class="{active:device==='desktop'}" aria-label="Desktop preview" @click="device='desktop'"><Icon name="dashboard" :size="16"/></button><button :class="{active:device==='mobile'}" aria-label="Mobile preview" @click="device='mobile'"><Icon name="file" :size="16"/></button></div></div><div class="preview-mode" aria-label="Preview mode"><button :class="{active:mode==='design'}" @click="changeMode('design')">Appearance preview</button><button :class="{active:mode==='live'}" @click="changeMode('live')">Test live chat <span></span></button></div><div :class="['widget-frame-stage',{mobile:device==='mobile'}]"><iframe ref="frame" :key="frameUrl" :src="frameUrl" title="Sahdev widget preview" @load="preview"/></div><div class="preview-caption"><Icon :name="mode==='design'?'sparkles':'chat'" :size="15"/><p>{{mode==='design'?'The actual embed renderer. Changes appear instantly; save to publish them.':connection||'Loading the saved widget…'}}</p></div><button v-if="conversationId&&mode==='live'" class="button secondary small" @click="emit('conversation',conversationId)">Open this conversation in inbox <Icon name="arrow" :size="15"/></button></aside>
 </div></div></template>
